add_action( 'woocommerce_shop_loop_item_title', 'perfectpixel_brand_in_loop', 6 );

function perfectpixel_brand_in_loop() {
	if ( ! taxonomy_exists( 'product_brand' ) ) {
		return;
	}
	$terms = get_the_terms( get_the_ID(), 'product_brand' );
	if ( ! $terms || is_wp_error( $terms ) ) {
		return;
	}
	$links = array();
	foreach ( $terms as $term ) {
		$links[] = '<a href="' . esc_url( get_term_link( $term ) ) . '">' . esc_html( $term->name ) . '</a>';
	}
	echo '<div class="perfectpixel-loop-brand" style="font-size:.8em;text-transform:uppercase;letter-spacing:.05em;opacity:.8">' . implode( ', ', $links ) . '</div>';
}
